import json
import re
from docx import Document

# Load data
with open('/root/employee_data.json') as f:
    data = json.load(f)

doc = Document('/root/offer_letter_template.docx')

PLACEHOLDER_RE = re.compile(r'\{\{([A-Z_]+)\}\}')


def replace_in_para(para):
    """Replace placeholders in a paragraph, handling split runs."""
    full_text = para.text
    if '{{' not in full_text:
        return

    new_text = full_text
    for match in PLACEHOLDER_RE.finditer(full_text):
        key = match.group(1)
        if key in data:
            new_text = new_text.replace(match.group(0), str(data[key]))

    if new_text != full_text and para.runs:
        para.runs[0].text = new_text
        for run in para.runs[1:]:
            run.text = ''


def process_table(table):
    """Process a table recursively (handles nested tables)."""
    for row in table.rows:
        for cell in row.cells:
            for para in cell.paragraphs:
                replace_in_para(para)
            for nested_table in cell.tables:
                process_table(nested_table)


# Handle conditional relocation section
relocation = data.get('RELOCATION_PACKAGE', 'No').strip().lower() == 'yes'

for para in doc.paragraphs:
    text = para.text
    if '{{IF_RELOCATION}}' in text and '{{END_IF_RELOCATION}}' in text:
        if relocation:
            # Keep content, strip only the markers
            new_text = text.replace('{{IF_RELOCATION}}', '').replace('{{END_IF_RELOCATION}}', '')
            # Also replace placeholders inside
            for match in PLACEHOLDER_RE.finditer(new_text):
                key = match.group(1)
                if key in data:
                    new_text = new_text.replace(match.group(0), str(data[key]))
        else:
            # Remove entire paragraph content
            new_text = ''

        if para.runs:
            para.runs[0].text = new_text
            for run in para.runs[1:]:
                run.text = ''
        continue

    replace_in_para(para)

# Process tables (with nested tables)
for table in doc.tables:
    process_table(table)

# Process headers and footers
for section in doc.sections:
    for para in section.header.paragraphs:
        replace_in_para(para)
    for para in section.footer.paragraphs:
        replace_in_para(para)

doc.save('/root/offer_letter_filled.docx')
print('Saved: /root/offer_letter_filled.docx')

